/* Revisão editorial: fontes atuais comparadas com o catálogo clássico. */
(()=>{const review={"alawar-s-vault":{"source":"https://www.tibiawiki.com.br/wiki/Alawar's_Vault_Quest","steps":["Escolha o acesso: diretamente pelo castelo de Senja, ou pela rota longa de Folda marcada no mapa. Alawar’s Vault e Dark Helmet são coletas diferentes.","Em Senja, desça no castelo. Remova o Fire Field que cobre a alavanca com Destroy Field; acione-a para retirar as Magic Walls. O desenho do mecanismo está na referência.","Na rota de Folda, obtenha 4503, abra a passagem de Pick, recolha 4501 e 4502. O Dark Helmet e seus itens ficam no baú de Folda; não são o prêmio do cofre.","Com 4502, alcance as portas do cofre. Limpe os minotauros e abra os dois baús: três White Pearls e uma Broadsword. O teleport de saída leva ao castelo de Senja."],"status":"wiki-compared","patches":[{"stage":7,"action":"Esse baú pertence à Dark Helmet de Folda. Recolha os itens e guarde 4502 para a continuação opcional até Alawar’s Vault."},{"stage":8,"action":"Aqui começa a coleta de Alawar’s Vault. Use 4502 e abra os dois baús ao norte; o teleport retorna ao castelo de Senja."}],"rewards":["white pearl","broadsword"],"rewardNote":"3 White Pearls e Broadsword. Dark Helmet e as chaves são da coleta de Folda, que pode ser feita no caminho longo.","guideNote":"O mapa mantém o caminho longo Folda → Dark Helmet → Alawar’s Vault. O acesso direto pelo castelo de Senja está explicado no roteiro e na fonte."},"annihilator":{"source":"https://www.tibiawiki.com.br/wiki/The_Annihilator_Quest","steps":["Entre na Hero Cave pelas Northern Ruins, ao norte de Edron, e acompanhe os trechos por andar até a porta de nível 100. Reserve cura para o combate final.","Reúna quatro personagens de nível 100+. Cada um ocupa um dos quatro pisos da alavanca; combine a ordem de entrada antes de acioná-la.","Na sala clássica dos seis Demons, mantenha a cura e abra o corredor derrotando os dois que bloqueiam a passagem. Não é necessário eliminar os seis para entrar no tesouro.","Escolha somente um baú. Depois da escolha, use o teleport de retorno. Angry Demons, outfits e achievements da página atual não fazem parte deste roteiro 7.4."],"status":"wiki-compared","patches":[]},"antidote-rune":{"source":"https://www.tibiawiki.com.br/wiki/Small_Health_Potion_Quest","steps":["Leve Rope e Shovel à entrada Premium do Goblin Temple. Siga o guia dessa caverna até o andar dos baús e retire a Pan.","Volte a Billy, na fazenda da área Premium de Rookgaard, levando a Pan na mochila. Fale hi → pan → yes, esperando a resposta entre mensagens.","No clássico, a troca é pela runa de curar veneno. O Wiki registra a substituição por potion em versões posteriores; não aplique essa recompensa moderna ao 7.4."],"status":"wiki-compared","patches":[{"stage":9,"speaker":"Billy","commands":["hi","pan","yes"],"commandNote":"Leve a Pan na mochila; no 7.4 a recompensa é a runa, não a potion moderna."}]},"barbarian-axe":{"source":"https://www.tibiawiki.com.br/wiki/Against_the_Spider_Cult_Quest","steps":["Acesse a Orc Cave a sudoeste de Edron. No primeiro subsolo, siga oeste e sul; no seguinte, procure a passagem oeste e desça no primeiro buraco.","Continue para leste e desça novamente. No andar dos Berserkers, vá norte e leste: os baús da Barbarian Axe e Scimitar estão em compartimentos distintos.","Controle os orcs antes de abrir os baús. A missão de destruir ovos para Daniel Steelsoul, descrita na página atual, é posterior ao 7.4 e não é requisito dessas coletas clássicas."],"status":"wiki-compared","patches":[],"guideNote":"O Wiki reúne estas coletas em Against the Spider Cult (missão adicionada em 8.1). Este roteiro não exige Daniel Steelsoul nem destruir ovos."},"battle-axe":{"source":"https://www.tibiawiki.com.br/index.php?stableid=331303&title=Thais_Quest","steps":["Entre no esgoto de Thais e siga o ramo oeste e sul até a passagem de Pick, próxima de 32301, 32257, 8.","Use Pick no piso indicado, desça e examine a pilha de ossos da Battle Axe. O marcador da recompensa localiza o compartimento.","Leve Rope para a volta. A página individual não existe atualmente no Wiki; consulte também a revisão antiga da Thais Quest nas fontes."],"status":"wiki-compared","patches":[]},"bear-room":{"source":"https://www.tibiawiki.com.br/wiki/Bear_Room_Quest","steps":["Entre pelas ruínas ao norte de Rookgaard. Desça pelos compartimentos de Trolls e Orcs até a sala dos Minotaurs e da Big Table.","Use Pick entre a mesa e os recipientes de água; desça, abra o baú da Key 4601 e retorne à sala superior.","Retire os objetos que escondem a alavanca acima da mesa. Acione-a para afastar a pedra; abra a porta com 4601 e enfrente o Bear.","Abra os três baús dos prêmios. Se alguém bloquear a porta de retorno, procure o Sewer da sala: é a saída alternativa e contém Spiders."],"status":"wiki-compared","patches":[{"stage":8,"action":"Retire o baú que encobre a alavanca acima da Big Table. Acione o mecanismo se a pedra estiver diante da porta."},{"stage":7,"action":"Depois da passagem de Pick entre a mesa e os recipientes de água, abra o baú e volte pela escada com a chave."}]},"behemoth":{"source":"https://www.tibiawiki.com.br/wiki/Behemoth_Quest","steps":["Entre em Cyclopolis, ao norte de Edron. Acompanhe o mapa por andar até o ramo dos Dragons, Fire Elementals e do Dragon Lord.","Na sala do Dragon Lord, remova com Destroy Field o campo que cobre a alavanca. Ative-a e retorne ao acesso da passagem das pedras.","Continue para a porta da quest e limpe a sala final antes dos baús. Nível de porta e quantidade de criaturas variam entre referências clássicas e servidores: confira o aviso de requisitos.","Recolha todos os recipientes da sala e planeje o retorno antes de sair. Não inclua Cyclops Drones ou Smiths modernos na previsão de criaturas do 7.4."],"status":"wiki-compared","patches":[{"stage":12,"action":"Mate o Dragon Lord, remova com Destroy Field o campo que cobre a alavanca e ative-a antes de voltar à passagem das pedras."}]},"berserker-treasure":{"source":"https://www.tibiawiki.com.br/wiki/Against_the_Spider_Cult_Quest","steps":["Use o mesmo acesso da Barbarian Axe na Orc Cave de Edron: oeste e sul no primeiro subsolo; depois passagem oeste e primeiro buraco.","Desça pelo ramo leste até o andar dos Berserkers. No corredor norte e leste, procure os baús complementares de White Pearls e ouro.","Recolha os recipientes separadamente dos baús de armas. Essa coleta clássica não exige pedir a missão moderna de ovos de Giant Spider."],"status":"wiki-compared","patches":[],"guideNote":"O Wiki reúne estas coletas em Against the Spider Cult (missão adicionada em 8.1). Este roteiro não exige Daniel Steelsoul nem destruir ovos."},"black-knight":{"source":"https://www.tibiawiki.com.br/wiki/Black_Knight_Quest","steps":["Saia de Venore pelo noroeste e siga norte à Black Knight Villa. Obtenha a Key 5010 na árvore a oeste da casa antes de entrar no porão.","Abra a porta com 5010 e acompanhe os trechos por andar. Passe pela porta de nível 50 e alcance o teleport após a área de Bonelords.","Combine a entrada da equipe: o blocker entra primeiro; os demais controlam as criaturas de apoio para não cercar o grupo.","Depois do Black Knight, use as duas árvores mortas ao sul da sala: uma guarda Crown Shield e a outra Crown Armor. Recolha ambas antes de voltar pelo teleport."],"status":"wiki-compared","patches":[]},"blood-herb":{"source":"https://www.tibiawiki.com.br/wiki/Blood_Herb_Quest","steps":["Saia para o oeste de Venore e atravesse Greenclaw Swamp levando Machete, Shovel e Rope. Alcance o acesso de 32753, 31974, 6.","Corte a vegetação, abra a passagem e atravesse o subsolo até a rampa. Ao subir, prepare-se para a Giant Spider.","Use a árvore junto à água, em 32769, 31968, 7, para recolher a Blood Herb. Você pode guardá-la ou levar a Wyda para a troca clássica pela Witchesbroom.","Torn Teddy e a Mini World Change citados na página atual são conteúdo posterior; a fala da troca fica na etapa de Wyda."],"status":"wiki-compared","patches":[{"stage":1,"speaker":"Wyda","commands":["hi","blood herb","yes"],"commandNote":"Com a planta na mochila. A alternativa de prêmio moderna não pertence ao 7.4."}],"needs":["Machete","Shovel","Rope"]},"captain-iglues-treasure":{"source":"https://www.tibiawiki.com.br/wiki/Captain_Iglues_Treasure_Quest","steps":["Desça pela torre de Poison Spiders ao norte de Rookgaard. Vá sudeste ao primeiro buraco; depois nordeste e desça novamente.","Atravesse os Poison Fields, desça e continue oeste e sul até o andar dos Skeletons e dos dois baús.","O baú direito dá os dois Salmons da quest. O esquerdo contém respawn diário de salmões e carta: pode estar vazio porque outro jogador já passou.","Leve Rope para refazer a subida. Não conte o respawn diário como uma recompensa individual garantida."],"status":"wiki-compared","patches":[]},"circle-room":{"source":"https://www.tibiawiki.com.br/wiki/Circle_Room_Quest","steps":["Entre na Drunken Fellow Mine, a oeste de Kazordoon, em 32494, 31974, 7. Desça pelo ramo nordeste; continue norte e leste até o próximo buraco.","Siga sul, oeste e norte pelos Dwarfs e desça. Continue para o sul até a porta de nível 32, deixando a Rope pronta para uma retirada.","A sala inferior pode cercar o personagem com Dwarf Guards e Geomancers. Avance com a equipe pelo lado leste e procure os baús ao sul.","Recolha Dwarven Axe e War Hammer. Preserve mana de cura: os Geomancers drenam mana e não devem ser ignorados num combate prolongado."],"status":"wiki-compared","patches":[]},"combat-knife":{"source":"https://www.tibiawiki.com.br/wiki/Combat_Knife_Quest","steps":["Desça no esgoto principal de Rookgaard, em 32097, 32205, 7, ou pela escada a leste do templo.","Siga leste e sul, controlando os Rats perto do baú. Procure atrás dos escombros no compartimento final.","Use o baú para obter a Combat Knife e retorne pela mesma rede de esgotos. Não há conversa com NPC para esta coleta."],"status":"wiki-compared","patches":[]},"crusader-helmet":{"source":"https://www.tibiawiki.com.br/wiki/Crusader_Helmet_Quest","steps":["Entre na Pick ’N Shovel Mine a oeste de Kazordoon, em 32548, 31988, 7. Desça para leste, pelo buraco seguinte e pelo longo ramo oeste.","Nos andares inferiores, siga norte, depois leste e novamente norte até a porta de nível 35. Prepare o grupo antes de descer.","Atravesse a área de Giant Spiders e continue oeste até o fim do túnel. Examine o esqueleto que contém o Crusader Helmet.","Teias e criaturas da referência atual podem diferir do clássico; uma passagem não desenhada deve ser conferida pela imagem da fonte e no servidor."],"status":"wiki-compared","patches":[]},"crystal-wand":{"source":"https://www.tibiawiki.com.br/wiki/Demona_Quest","steps":["Entre no Maze of Lost Souls pela região de Northport, acione o mecanismo do labirinto e siga a referência de andares até Demona.","Depois da porta de nível 60, avance ao pentagrama e ao ramo nordeste e norte. Prepare a equipe para os Warlocks dos salões internos.","Desça ao salão de recompensas e recolha Crystal Wand e a recompensa clássica de SD conforme a implementação do servidor.","O Wiki atual mostra emblemas, livros e criaturas posteriores. Eles não substituem automaticamente as runas do 7.4. O teleport de saída fica no ramo sudoeste da biblioteca."],"status":"wiki-compared","patches":[]},"dark-armor":{"source":"https://www.tibiawiki.com.br/wiki/Against_the_Spider_Cult_Quest","steps":["Entre na Orc Cave a sudoeste de Edron. Desça pelo caminho oeste e sul; no andar seguinte, vá oeste e norte ao primeiro quarto a leste.","Desça e siga norte ao poço da Giant Spider. Prepare cura e saída antes de entrar; o acesso ao poço é pelo lado nordeste.","Use o corpo dentro do poço para recolher a Dark Armor. O combate dos ovos e o relatório a Daniel Steelsoul são missões posteriores ao 7.4."],"status":"wiki-compared","patches":[],"guideNote":"O Wiki reúne estas coletas em Against the Spider Cult (missão adicionada em 8.1). Este roteiro não exige Daniel Steelsoul nem destruir ovos."},"dead-archer":{"source":"https://www.tibiawiki.com.br/wiki/Thais_Quest","steps":["Abra com Shovel a entrada da Troll Cave a leste de Thais, em 32493, 32259, 7. Desça pelo ramo leste duas vezes.","No andar de Orcs, vá ao corredor sul. Atravesse os campos de veneno com cura preparada e controle o Slime perto dos corpos.","Use o corpo do arqueiro ao norte e examine os recipientes do local. Se houver lixo ou cadáveres sobre o corpo, retire-os para conseguir abri-lo.","Mantenha os fluidos e prêmios clássicos da lista; as potions atuais da página não são a apresentação dos itens no 7.4."],"status":"wiki-compared","patches":[]},"fibula":{"source":"https://www.tibiawiki.com.br/wiki/Deeper_Fibula_Quest","steps":["Chegue a Fibula pelo túnel ao sul de Thais. Se precisar da Key 3940, fale hi → key → yes a Dermot, levando 2.000 gp.","Use o poço da vila. Abra a porta da dungeon com 3940, siga pela porta mais à direita e desça à sala dos dois teleports.","A porta de nível 50 leva à parte profunda sem retorno imediato. Só entre com suprimentos para completar o trajeto.","Depois do teleport, vá oeste através dos fields e use o buraco de 32219, 32401, 10 para obter a Key 3980. Volte, siga sul pela ponte e destranque a porta.","Atravesse minotauros e dragões. Recolha os cinco corpos marcados; apague o Fire Field sobre o corpo do Tower Shield se necessário.","O teleport no sudoeste da caverna, perto de 32234, 32502, 10, retorna à entrada da dungeon."],"status":"wiki-compared","patches":[],"needs":["2.000 gp se precisar comprar a Key 3940 com Dermot"]},"demon-helmet":{"source":"https://www.tibiawiki.com.br/wiki/The_Demon_Helmet_Quest","steps":["Entre nas Northern Ruins de Edron. A Key 6010 vem da Parchment Room: remova o campo e o parchment com a equipe pronta para os Demons.","Na Demon Hell, passe pela porta de nível 100 e use 6010. Dois ajudantes precisam ocupar os pisos da sala lateral para remover a parede de acesso.","Atravesse Fire Elementals, use os teleports e acompanhe os buracos do percurso. Uma queda errada pode levar a outro respawn de Demons.","Na sala final, ative a alavanca leste para liberar a saída antes de prolongar o combate. Os três baús ficam a oeste.","Recolha Demon Helmet, Demon Shield e Steel Boots. A alavanca final libera o portal; não substitui os pisos da passagem inicial. Demon outfits e addons não são requisitos do 7.4."],"status":"wiki-compared","patches":[{"stage":2,"action":"Use 6010, obtida na Parchment Room. Dois ajudantes mantêm os pisos da sala lateral acionados para abrir a parede; confira o desenho.","visualRequired":true},{"stage":9,"action":"Na sala final, ative a alavanca leste para abrir o portal de saída; os baús dos prêmios estão a oeste.","warning":"Não confunda a saída final com os dois pisos da passagem inicial."}],"needs":["Dois ajudantes para os pisos da parede de acesso"]},"demona-ring":{"source":"https://www.tibiawiki.com.br/wiki/Demona_Quest#Missão_03:_Wand_of_Might_Hall","steps":["Use o acesso do Maze of Lost Souls até Demona e atravesse a porta de nível 60 com preparo para Warlocks.","A partir do pentagrama, vá nordeste e desça; siga norte ao salão do poço de lava. Suba por uma das escadas ao norte.","Limpe o andar superior e abra os dois baús nos cantos sul para os anéis. O marcador deste guia é da região, não de cada baú.","Retorne ao ramo da biblioteca para o teleport de saída. A localização clássica de cada recipiente ainda precisa de confirmação no servidor."],"status":"wiki-compared","patches":[]},"devil-helmet":{"source":"https://www.tibiawiki.com.br/wiki/Mintwallin_Quest","steps":["Entre pelo Ancient Temple e alcance o labirinto de Mintwallin. A chave da sala do laboratório é 3610, obtida no buraco coberto por Fire Field da sala dos Cyclops.","Combine pelo menos dois jogadores. Um mantém o piso de pressão acionado; o outro atravessa a passagem que ele libera.","Passe pela porta de nível 30 e abra a passagem com 3610. Limpe a sala e examine os baús do Devil Helmet e Halberd.","Se ambos quiserem o prêmio, refaçam o mecanismo alternando quem mantém o piso. Liberar a grade uma vez não garante o acesso simultâneo dos dois."],"status":"wiki-compared","patches":[{"stage":2,"action":"Um jogador permanece neste piso; o outro atravessa a grade. Repitam trocando de função se ambos precisarem do prêmio."},{"stage":1,"action":"A chave vem do buraco sob Fire Field junto aos baús da sala dos Cyclops; use Destroy Field antes de examinar o buraco."}]},"double-hero":{"source":"https://www.tibiawiki.com.br/wiki/The_Hero_Cave_Quest","steps":["Desça a Hero Cave de Edron até o corredor dos altares de sacrifício, ao sul dos andares principais.","Prepare o combate contra os dois Heroes e as criaturas de apoio. Controle a entrada para evitar que o grupo fique cercado.","Depois de limpar, examine os dois baús no sul da sala: Club Ring e Red Gem. Refaça o acesso da Hero Cave para voltar."],"status":"wiki-compared","patches":[]},"doublet":{"source":"https://www.tibiawiki.com.br/wiki/Doublet_Quest","steps":["Vá ao estábulo ao norte da loja de Tom, em Rookgaard, próximo de 32080, 32181, 7.","Desça ao porão e procure a tábua solta indicada pelo marco do mapa. Use o chão nesse ponto para obter a Doublet.","A recompensa não está num baú comum. Volte pelas escadas do estábulo."],"status":"wiki-compared","patches":[]},"draconia":{"source":"https://www.tibiawiki.com.br/wiki/Draconia_Quest","steps":["Acesse Hellgate por Ab’Dendriel com a Key 3012. Siga a rota de referência até Redbone Castle e a pirâmide de Draconia.","Obtenha 3001 no esqueleto do lado esquerdo; abra a porta direita ao sul. Atravesse o tapete encostado à parede para evitar quedas e pegue 3002 no caixão.","Use 3002, acione as alavancas A e B para mover a pedra e continue a sequência de chaves. As imagens da fonte mostram cada recipiente.","Nos salões superiores, remova os fields que escondem 3004 e 3006; obtenha 3005 junto ao pilar. Abra as portas correspondentes antes de subir.","Dois jogadores coordenam os pisos: um sustenta o primeiro enquanto o outro ocupa o piso da sala liberada. Use o teleport para pegar 3007.","Passe pela porta de nível 25 e recolha os prêmios. Obtenha 3008 na estante; no andar final, ajuste esquerda → direita → esquerda → direita para ativar a saída."],"status":"wiki-compared","patches":[{"stage":6,"action":"Mantenha o primeiro piso pressionado enquanto o parceiro entra na sala liberada e ocupa o segundo. Não solte o mecanismo antes do sinal."},{"stage":7,"action":"Coordene com quem ocupa o primeiro piso para liberar o acesso à Key 3007. Os dois mecanismos dependem dos personagens, não de uma fala de NPC."}],"needs":["Key 3012 para Hellgate","Chaves 3001–3008","Destroy Field Runes","Pelo menos dois personagens para os pisos"]},"dragon-corpse":{"source":"https://www.tibiawiki.com.br/wiki/Dragon_Corpse_Quest","steps":["Entre na Bear Cave a leste de Rookgaard e escolha o ramo sul. Leve Shovel, Rope e Scythe, além de cura para ida e volta.","No fim do corredor, abra a pilha de pedras e desça. Corte o trigo se ele bloquear a passagem.","Atravesse os Fire Fields sem parar sobre eles e use o corpo do Dragon para obter a bag com os equipamentos.","Guarde cura para atravessar os fields novamente. A ausência moderna de perda de mochila em Rookgaard não se aplica automaticamente ao 7.4."],"status":"wiki-compared","patches":[],"needs":["Scythe","Shovel","Rope","Cura para atravessar Fire Fields na ida e na volta"]},"dragon-tower":{"source":"https://www.tibiawiki.com.br/wiki/Shadowthorn_Quest","steps":["Entre em Shadowthorn pela região a leste de Venore. Alcance a torre pela subida perto de 33075, 32166, 8.","Suba os andares dos elfos, mantendo espaço para recuar nas escadas. Os Dragons da torre podem ser acessados pelo andar acima.","No topo, examine os dois baús em lados opostos da sala. Recolha as flechas e gemas antes de descer.","Thornfire, Firestarters e montarias da página atual não fazem parte das etapas deste roteiro clássico."],"status":"wiki-compared","patches":[]},"edron-goblin":{"source":"https://www.tibiawiki.com.br/wiki/Edron_Goblin_Quest","steps":["Desça pelo esgoto a sudoeste do depot de Edron, em 33165, 31827, 7. Atravesse o túnel até a área de grama a oeste.","Vá sudoeste à colina dos Goblins e desça em 33107, 31847, 7. No subsolo, siga noroeste e desça; depois nordeste à passagem seguinte.","Controle os Goblins e Wasps da sala do trono. Abra os dois baús ao lado do trono para Steel Shield e Silver Amulet."],"status":"wiki-compared","patches":[]},"elvenbane":{"source":"https://www.tibiawiki.com.br/wiki/To_Blind_the_Enemy_Quest","steps":["Vá ao castelo a oeste de Ab’Dendriel. Use Shovel no acesso cercado por quatro pedras e siga norte e oeste até subir no interior.","Contorne pelo norte e oeste, entre na torre central e atravesse o andar de Poison Fields. Prepare o combate com o Dragon antes de subir.","No penúltimo andar, examine dois baús e duas gavetas, controlando Demon Skeletons e Elf Arcanists.","O espelho, o globo e o relatório a Eroth descritos na missão moderna não são necessários para a coleta clássica. Este guia mantém somente os recipientes antigos."],"status":"wiki-compared","patches":[],"guideNote":"A missão do globo com Eroth é posterior. Este guia descreve os recipientes clássicos, sem exigir o espelho."},"emperor-s-cookies":{"source":"https://www.tibiawiki.com.br/wiki/Emperor's_Cookies_Quest","steps":["No trono de Kazordoon, siga norte pelo corredor de estátuas até a biblioteca. Procure a passagem entre a estante e a parede norte para obter 3800.","Não caia no buraco da passagem: ele leva ao túnel da montanha. Volte e abra o quarto com 3800.","No baú do quarto, pegue os Cookies e 3801. Desça aos alojamentos, abra o quarto correspondente com 3801 e obtenha 3802.","A 3802 serve para Dwacatra e passagens das minas. O ingresso moderno na Explorer Society não é necessário para pegar essas chaves clássicas."],"status":"wiki-compared","patches":[]},"explorer-brooch":{"source":"https://www.tibiawiki.com.br/wiki/The_Explorer_Society_Quest","steps":["Vá à taverna Jolly Axeman em Kazordoon. Desça pelo esgoto da taverna levando Rope.","Explore o compartimento do corpo marcado e use o cadáver para retirar o Explorer Brooch. Confira os Rats e o retorno pelo acesso da taverna.","A página atual redireciona para a Explorer Society, adicionada depois do 7.4. A coleta antiga deste brooch não implica completar essa missão moderna."],"status":"wiki-compared","patches":[],"guideNote":"O Wiki redireciona para Explorer Society. Mantida somente a coleta clássica do esgoto; o conteúdo moderno não foi convertido em requisito."},"fanfare":{"source":"https://www.tibiawiki.com.br/wiki/Fanfare_Quest","steps":["Pegue a Key 3520 na box do canto nordeste da casa próxima ao barco de Carlin, em 32376, 31802, 7, se a porta da cripta estiver fechada.","Entre no cemitério a leste de Carlin e desça pela escada ao sul. Abra a porta oeste com a chave.","Desça pelo buraco, siga norte e use o baú da Fanfare. Depois retorne pela cripta."],"status":"wiki-compared","patches":[{"stage":0,"action":"A Key 3520 fica na box do canto nordeste da casa. Leve-a se a porta da cripta não estiver aberta."}],"needs":["Key 3520 (se a porta estiver fechada)"]},"fire-axe":{"source":"https://www.tibiawiki.com.br/wiki/Fire_Axe_Quest","steps":["Entre no Dragon Lair de Edron e siga os trechos por andar até a porta de nível 60. Prepare a equipe para Dragons e Dragon Lords.","Recolha os recipientes complementares do andar; localize a passagem de terra indicada e use Pick.","Desça e examine o esqueleto da Fire Axe. Guarde Rope e cura para a volta pela mesma passagem."],"status":"wiki-compared","patches":[]},"geomancer":{"source":"https://www.tibiawiki.com.br/wiki/Thais_Quest","steps":["Entre pelo acesso de Mount Sternum. Desça e siga noroeste ao buraco; continue norte, oeste e leste até o próximo andar.","Atravesse os mortos-vivos, vá leste e desça novamente. A sala de recompensas fica no ramo leste, protegida por Dwarf Guards e um Geomancer.","Controle o Geomancer e sua drenagem de mana antes de abrir os recipientes de anel e gemas. Reserve cura para refazer as subidas."],"status":"wiki-compared","patches":[]},"ghoul-room":{"source":"https://www.tibiawiki.com.br/wiki/Mintwallin_Quest","steps":["Entre no Ancient Temple ao norte de Thais e alcance os túneis do labirinto, atravessando a área de Poison Fields.","Investigue o ramo dos mortos-vivos e use o esqueleto para obter a Key 3600. Clique no poço próximo para descer.","Abra a porta com 3600, elimine os Ghouls e recolha Garlic Necklace e Club Ring. Use o poço de retorno para sair da pequena sala."],"status":"wiki-compared","patches":[]},"giant-smithhammer":{"source":"https://www.tibiawiki.com.br/wiki/The_Explorer_Society_Quest","steps":["Vá ao acampamento de Cyclops e Minotaurs em Plains of Havoc. Desça na estrutura norte, próxima de 32780, 32234, 7.","Prepare-se para Cyclops, Minotaur Guards e Mages. A caixa fica na sala imediatamente ao sul do acesso.","Recolha o Giant Smithhammer e os itens da coleta clássica. A entrega a Mortimer ou Angus pertence à Explorer Society posterior; não é etapa obrigatória no 7.4."],"status":"wiki-compared","patches":[],"guideNote":"A coleta do martelo é separada da entrega à Explorer Society, adicionada em versão posterior ao 7.4."},"goblin-temple":{"source":"https://www.tibiawiki.com.br/wiki/Goblin_Temple_Quest","steps":["Abra com Shovel o acesso Premium em Rookgaard. Siga norte, desça as rampas e suba pelo ponto de Rope do percurso.","Continue norte, desça as passagens seguintes e vá sul à ponte dos Goblins. Atravesse sem permanecer no alcance das pedras.","No andar abaixo, vá sul e oeste à rampa. Depois norte à escada final; prepare Minotaur, Wasp, Goblins e Orc Spearman.","Abra os baús do templo. A Pan pode ser trocada com Billy pela runa clássica; o Small Axe pode ser trocado com Al Dee por Pick."],"status":"wiki-compared","patches":[]},"griffin-shield":{"source":"https://www.tibiawiki.com.br/wiki/Demona_Quest","steps":["Entre no Maze of Lost Souls pela região de Northport. Ative o mecanismo de acesso ao labirinto e siga as referências para Demona.","Na região dos Gates of Demona, controle Dwarf Guards, Minotaur Guards, Stone Golems e Elf Arcanists antes de recolher os corpos.","Examine separadamente os recipientes de Griffin Shield, Dwarven Axe e Obsidian Lance. Esses prêmios ficam antes da incursão profunda nos Warlocks."],"status":"wiki-compared","patches":[]},"heaven-blossom":{"source":"https://www.tibiawiki.com.br/wiki/Heaven_Blossom","steps":["Vá a Shadowthorn a leste de Venore e procure o subsolo do setor nordeste, próximo de 33103, 32155, 8.","A referência do Wiki indica um barril com Heaven Blossom. Confira o acesso e o recipiente no servidor antes de descer em outros andares.","A posição anterior era apenas uma área. O marcador continua sem percurso SQM confirmado e a disponibilidade histórica no 7.4 permanece em revisão."],"status":"wiki-compared","patches":[]},"iron-hammer":{"source":"https://www.tibiawiki.com.br/wiki/Iron_Hammer_Quest","steps":["Abra com Shovel a grande pilha de pedras a oeste de Kazordoon, em 32448, 31991, 7. Prepare Minotaurs e Archers.","No subsolo, siga noroeste até a sala com camas. A caixa do Iron Hammer fica entre as camas.","Use o recipiente e retorne pelo acesso da Shovel, mantendo Rope e cura disponíveis."],"status":"wiki-compared","patches":[]},"iron-helmet":{"source":"https://www.tibiawiki.com.br/wiki/Iron_Helmet_Quest","steps":["Vá à árvore a oeste do acampamento de Cyclops e Minotaurs em Plains of Havoc, próxima de 32769, 32225, 7.","Procure o corpo parcialmente escondido atrás da árvore. Use-o para recolher o helmet e os itens registrados na coleta.","Cuidado com criaturas trazidas do acampamento. A disponibilidade exata da runa e do recipiente clássico deve ser conferida no servidor."],"status":"wiki-compared","patches":[]},"isle-of-the-mists":{"source":"https://www.tibiawiki.com.br/wiki/Isle_of_the_Mists_Quest","steps":["Atravesse Plains of Havoc até o teleport em 32831, 32294, 7. O caminho terrestre é a parte perigosa desta coleta.","O Wiki descreve o acesso como restrito a Druids. Confirme essa condição no seu servidor 7.4 antes de organizar a viagem.","Na ilha, desça pela escada única do andar superior, abra a caixa das duas Small Emeralds e examine as estantes do livro.","Use o acesso de retorno da ilha. Não interprete o marco de superfície como um caminho navegável pelo mar."],"status":"wiki-compared","patches":[]},"katana":{"source":"https://www.tibiawiki.com.br/wiki/Katana_Quest","steps":["Abra com Shovel a sepultura central a nordeste de Rookgaard. Vá oeste ao buraco e desça à área dos Skeletons.","Continue leste ao ponto de Rope, suba à sala dos Rotworms e alcance a descida do outro lado sem ficar cercado.","Atravesse o veneno e procure a Key 4603 no corpo do ramo norte. Volte sul, siga leste dos fields e desça à porta da chave.","Abra com 4603 e use a alavanca escondida atrás do pilar norte para liberar a sala. Recolha Katana e Viking Helmet nos corpos.","Se a porta for fechada por outro jogador, o teleport interno permite sair perto do acesso de subida."],"status":"wiki-compared","patches":[{"stage":4,"action":"A alavanca fica atrás do pilar norte. Abra a sala dos corpos; se alguém a fechar novamente, use o teleport interno para sair."}]},"kingdom-of-kormarak":{"source":"https://www.tibiawiki.com.br/wiki/Mintwallin_Quest","steps":["No labirinto do Ancient Temple, siga o ramo norte até a placa do reino morto de Kormarak.","Suba a escada próxima e atravesse o teleport. Prepare Ghouls, Skeletons e Demon Skeleton na sala.","Use o corpo no centro para os equipamentos. Trata-se de respawn do mundo: os itens podem ter sido retirados por outro jogador.","Retorne pelo teleport no sul da sala para voltar ao labirinto."],"status":"wiki-compared","patches":[]},"present-box":{"source":"https://www.tibiawiki.com.br/wiki/Present_Quest","steps":["Siga o caminho da Bear Room até a sala da mesa e da alavanca da pedra. O baú próximo ao mecanismo contém a backpack com Present Box.","Guarde a caixa intacta e volte à academia de Rookgaard. A visita inicial a Seymour é opcional para esta troca.","Com a Present Box na mochila, fale hi → present box → yes a Seymour. A recompensa da troca é o Legion Helmet."],"status":"wiki-compared","patches":[{"stage":6,"speaker":"Seymour","commands":["hi","present box","yes"],"warning":"Guarde a Present Box intacta até a troca."}]},"life-ring":{"source":"https://www.tibiawiki.com.br/wiki/Thais_Quest","steps":["Desça o Ancient Temple e siga sul, depois leste pelos Orcs até a ponte. Se estiver recolhida, use a alavanca do ramo sul.","Atravesse a ponte, continue leste e sul pelos Bonelords até o fim junto à água. Use Pick na parede oeste, perto de 32437, 32239, 10.","Ao descer, prepare três Bonelords. A caixa do Life Ring e Dragon Necklace fica no canto nordeste da sala."],"status":"wiki-compared","patches":[]},"longsword":{"source":"https://www.tibiawiki.com.br/wiki/Longsword_Quest","steps":["Entre na Troll Cave a leste da Dwarf Bridge, atrás da árvore de 32663, 31962, 7.","Vá sul ao próximo andar e depois norte. Controle Minotaur Archer e Mage do quarto norte antes de se aproximar dos baús.","Examine os recipientes no norte da sala grande para espada e itens complementares. Confira também os marcos separados dos recipientes no mapa."],"status":"wiki-compared","patches":[]},"mad-mage-room":{"source":"https://www.tibiawiki.com.br/wiki/Mintwallin_Quest","steps":["Acesse Mintwallin pelo labirinto do Ancient Temple. Pegue 3620 na cômoda do dormitório sul e abra a prisão no lado oeste da cidade.","Leve sete Red Apples a A Prisoner. Resolva o enigma com a sequência indicada na etapa do NPC para obter a Key 3666.","Volte ao labirinto e à porta de nível 40 da Mad Mage Room. Prepare Dragon, Giant Spider, Bonelord e Demon Skeletons.","Abra a porta com 3666, suba e limpe os Demon Skeletons. Abra os baús individuais antes de procurar os respawns diários separados.","A 3667 fica no corpo sob o lixo do ramo dos Cyclops e Rats. Ela serve para a continuação do laboratório; não é a chave da primeira porta de prêmio."],"status":"wiki-compared","patches":[{"stage":2,"speaker":"A Prisoner","commands":["hi","riddle","PD-D-KS-P-PD","yes","yes","yes","yes"],"warning":"Leve sete Red Apples; a chave de entrada da prisão é 3620.","objective":"Key 3666 para a porta do prêmio da Mad Mage Room.","detailSource":"https://www.tibiawiki.com.br/wiki/A_Prisoner"}],"needs":["7 Red Apples","Key 3620 para a prisão","Key 3666 (obtida com A Prisoner)"]},"medusa-shield":{"source":"https://www.tibiawiki.com.br/wiki/Medusa_Shield_Quest","steps":["Saia de Darashia para oeste. Use Rope no acesso de Drefia e Parcels ou Levitate na subida seguinte; continue pelos buracos até chegar às ruínas.","Desça no setor noroeste de Drefia e atravesse os Necromancer Halls ao norte. Alcance o pentagrama e siga leste à porta de nível 60.","Suba à sala dos mortos-vivos e controle Necromancers, Vampires, Demon Skeletons e as criaturas de apoio.","Abra o caixão no lado leste para Medusa Shield, Blue Robe e Skull Staff. Volte pelas escadas sem depender de teleport não confirmado."],"status":"wiki-compared","patches":[]},"minotaur-hell":{"source":"https://www.tibiawiki.com.br/wiki/Minotaur_Hell_Quest","steps":["Entre nas ruínas ao norte de Rookgaard, siga o ramo dos Trolls e avance norte pelo Wolf Maze.","Antes das últimas descidas, controle Orcs, Wolves e Minotaurs nas passagens estreitas. Não avance ao centro da sala se não puder suportar o grupo.","No andar final, os três recipientes da quest ficam no sudoeste, entre a escada e a Big Table.","Abra cada box para Carlin Sword, flechas e Fishing Rod. Os outros objetos de respawn espalhados na sala não são recompensas individuais garantidas."],"status":"wiki-compared","patches":[]},"mintwallin-cyclops":{"source":"https://www.tibiawiki.com.br/wiki/Mintwallin_Quest","steps":["No labirinto de Mintwallin, alcance o setor nordeste e desça à sala dos minotauros rebeldes. Siga sul e suba ao ramo do mecanismo.","Se usar a alavanca, a parede se move e pode prender o jogador com os Cyclops. A alternativa de porta usa a Key 3667, obtida na Mad Mage Room.","Limpe a sala e abra os baús a noroeste para a Small Diamond e os demais itens do servidor.","Remova o Fire Field ao lado dos baús e use o buraco para obter 3610, necessária ao laboratório do Devil Helmet. A saída pelo buraco norte volta à sala dos minotauros."],"status":"wiki-compared","patches":[]},"naginata":{"source":"https://www.tibiawiki.com.br/wiki/Thais_Quest","steps":["Entre no Dragon Lair ao norte de Alatar Lake em Thais. Desça pelos buracos do setor sudeste e siga ao ramo sul até subir à área dos dragões.","Alcance a pequena sala norte da Dragon Lair. Se a pedra cobrir o buraco, use Pick para abrir a descida.","Passe pela porta de nível 40 e prepare os Dragon Lords antes da última queda. O baú da Naginata fica ao norte da caverna final.","Não conte Dragon Hatchlings ou Dragon Lord Hatchlings da documentação atual como criaturas do 7.4."],"status":"wiki-compared","patches":[]},"noble-armor":{"source":"https://www.tibiawiki.com.br/wiki/Thais_Quest","steps":["Entre pelo norte de Mount Sternum. No subsolo, siga oeste e norte, desça; depois norte, leste, sul e leste para a subida até Skjaar.","Confira se a porta da chave já está aberta antes de pagar. Se precisar, leve 1.000 gp e responda ao teste de Skjaar para receber 3142.","Atravesse a porta de nível 35 e use 3142 na porta trancada. Mate os Ghouls e abra os baús de Noble Armor e Crown Helmet.","O roteiro do teste e as palavras copiáveis estão na etapa de Skjaar; não confunda a porta de nível com a porta que recebe a chave."],"status":"wiki-compared","patches":[{"stage":1,"speaker":"Skjaar","commands":["hi","key","yes","yes","redips","7","black","yes"],"warning":"O teste custa 1.000 gp. Confira antes se a porta da Key 3142 já está aberta.","objective":"Key 3142 para a porta trancada depois da passagem de nível 35."}],"needs":["1.000 gp para o teste de Skjaar","Key 3142 (obtida no teste)"]},"orc-fortress":{"source":"https://www.tibiawiki.com.br/wiki/Orc_Fortress_Quest","steps":["Desça pelo acesso de Ulderek’s Rock em 32889, 31770, 7. Atravesse leste até a escada interna em 32957, 31767, 8.","Limpe Orc Leaders, Warlords e o Dragon antes de seguir leste e norte pela porta de nível 40.","Os três baús ficam ao norte da sala do rei: Fire Sword, Knight Armor e Knight Axe.","Não é preciso falar com Orc King para pegar esses baús. O primeiro hi invoca orcs; faça esse diálogo apenas com a equipe pronta, por exemplo na missão dos Djinns."],"status":"wiki-compared","patches":[]},"orc-shaman":{"source":"https://www.tibiawiki.com.br/wiki/Orc_Shaman_Quest","steps":["Atravesse o pântano a nordeste dos portões de Venore até o acampamento de orcs, perto de 33055, 32029, 7.","Suba ao telhado, desça pelo buraco e pelo acesso do solo. No subsolo, siga leste e desça novamente.","Controle Orcs, Spearmen e Shaman da sala. O recipiente de Magic Light Wand e itens complementares fica no canto sudeste."],"status":"wiki-compared","patches":[]},"ornamented-shield":{"source":"https://www.tibiawiki.com.br/wiki/Ornamented_Shield_Quest","steps":["Entre no Dragon Lair de Plains of Havoc e desça pelos Dragons. Prepare o grupo antes do andar de Dragons e Dragon Lords.","Use Pick na passagem marcada na parte sul. No andar do Fire Devil, examine o corpo coberto por Fire Field a nordeste para Ornamented Shield.","O prêmio clássico deste corpo não exige completar a continuação moderna do piso de pressão. Refaça a subida com Rope.","A Key 3702 registrada nas referências antigas deve ser conferida no servidor; a página atual descreve uma configuração diferente."],"status":"wiki-compared","patches":[]},"panpipe":{"source":"https://www.tibiawiki.com.br/wiki/Panpipe_Quest","steps":["Antes de entrar em Jakundaf Desert, use a pedra ao sul da entrada, em 32652, 32107, 7, para obter a Key 4055.","Abra a dungeon com Shovel e desça até o fim. Contorne oeste e sul, suba e siga noroeste passando pela biblioteca.","Suba com Rope nos pontos indicados, vá sul e depois sudeste até a porta 4055 e o Fire Devil.","Abra o baú de Panpipes, Power Ring e duas Small Amethysts. O documento atrás da porta de Crowbar é uma pista opcional, não um requisito para a recompensa."],"status":"wiki-compared","patches":[{"stage":0,"action":"Dê use na pedra ao sul da entrada da dungeon, em 32652, 32107, 7. Pegue a chave antes de descer."}],"needs":["Key 4055 (na pedra ao sul da entrada)","Rope"]},"parchment-room":{"source":"https://www.tibiawiki.com.br/wiki/The_Demon_Helmet_Quest","steps":["Desça a Hero Cave e use Pick na passagem indicada para o corredor da Parchment Room.","Prepare o Demon da sala e combine a ação no caixão: mover o Parchment pode invocar quatro Demons adicionais.","Abra o caixão para a bag e a Key 6010. Guarde a chave para Demon Helmet; retire-se pelo acesso de entrada depois de organizar os summons."],"status":"wiki-compared","patches":[{"stage":4,"warning":"Mover o Parchment pode invocar quatro Demons. Organize o blocker e a cura antes da ação.","action":"Abra o caixão e guarde a Key 6010 para Demon Helmet."}]},"small-axe":{"source":"https://www.tibiawiki.com.br/wiki/Pick_Quest","steps":["Para a rota do mapa, abra com Shovel a caverna Premium de Skeletons e siga o caminho até os dois caixões. O direito contém o Small Axe.","Outras opções são loot de Goblins ou respawns de Small Axe. A troca não exige usar o recipiente Premium específico.","Leve um Small Axe a Al Dee em Rookgaard e fale hi → pick → yes. Ele recebe o machado e entrega a Pick."],"status":"wiki-compared","patches":[{"stage":1,"speaker":"Al Dee","commands":["hi","pick","yes"],"commandNote":"Leve um Small Axe, de qualquer fonte válida do servidor."}]},"plate-armor":{"source":"https://www.tibiawiki.com.br/wiki/Plate_Armor_Quest","steps":["Viaje de Venore para Darashia com Captain Fearless. O desvio para o Ghost Ship é aleatório; uma viagem normal não significa que a quest falhou.","Se o navio fantasma aparecer, procure a escada para seu interior e examine o caixão da Plate Armor.","Recolha a armadura antes de usar a saída do navio. O marcador do atlas é uma referência da instância, não uma rota terrestre ou marítima até ela."],"status":"wiki-compared","patches":[{"stage":0,"action":"O navio é um desvio aleatório da viagem Venore–Darashia. O ponto do atlas não é um acesso alcançável caminhando."}]},"poison-daggers":{"source":"https://www.tibiawiki.com.br/wiki/Against_the_Spider_Cult_Quest","steps":["Na Orc Cave de Edron, siga oeste e sul no primeiro subsolo; no seguinte, oeste e norte até o primeiro quarto a leste.","Desça ao piso diferente do corredor norte. Vá norte, depois oeste e sul à sala do recipiente.","Abra a backpack das Poison Daggers e Poison Arrows. A coleta não exige a missão de ovos adicionada à região em versões posteriores."],"status":"wiki-compared","patches":[],"guideNote":"O Wiki reúne estas coletas em Against the Spider Cult (missão adicionada em 8.1). Este roteiro não exige Daniel Steelsoul nem destruir ovos."},"postman-missions":{"source":"https://www.tibiawiki.com.br/wiki/The_Postman_Missions_Quest","steps":["Comece com Kevin e siga a ordem das missões. As viagens exigidas são Thais–Carlin, Femor Hills–Edron, Edron–Venore e Kazordoon–Cormaya.","Volte à sede entre as tarefas: mailbox de Folda, conta de David Brassacres, vinte Bones e presente intacto para Dermot.","Para os uniformes, siga Hugo → Kevin → Talphion → Kevin → Queen Eloise → Kevin → Noodles → Kevin → Hugo → Kevin. As falas e repetições estão em cada etapa.","Recolha as medidas dos seis funcionários; Lokur encaminha a Kroox. Leve Arrows, Grapes e dinheiro para Olrik antes de viajar.","Com a missão de Waldo ativa, examine o corpo para Post Horn. Peça a promoção, libere 500 oz e use a bag na mailbox de Santa em Vega.","Entregue a carta a Markwin, preparando seus guardas. Volte a Kevin e peça advancement para concluir."],"status":"wiki-compared","patches":[]},"power-bolts":{"source":"https://www.tibiawiki.com.br/wiki/Power_Bolts_Quest","steps":["Desça no buraco ao sul do templo de Plains of Havoc, em 32815, 32280, 7, preparado para a Giant Spider.","O corpo na parte norte contém a bag de Power Bolts e Burst Arrows. Examine também a pilha de ossos da Two Handed Sword.","O livro fica no corpo ao sul do teleport. Talon e Throwing Stars de respawn são coletas do mundo e podem estar ausentes.","Reserve a saída pelo teleport e não deixe a criatura bloquear o acesso durante a coleta."],"status":"wiki-compared","patches":[{"stage":2,"action":"A bag de Power Bolts e Burst Arrows está no corpo norte. A Two Handed Sword fica na pilha de ossos; o Talon de respawn pode estar ausente."}]},"power-ring":{"source":"https://www.tibiawiki.com.br/wiki/Power_Ring_Quest","steps":["Em Femor Hills, siga o rio pelo lado sul, ao norte do tapete. Suba, vá leste para dentro da montanha e desça pela escadaria norte.","Continue nordeste ao próximo buraco. Na sala de Goblins e Wolves, vá sudoeste e desça outra vez.","Os baús de Power Ring e Bronze Amulet ficam ao norte, perto dos Beer Casks. Controle os Goblins que atacam desde a entrada."],"status":"wiki-compared","patches":[]},"purple-tome":{"source":"https://www.tibiawiki.com.br/wiki/Demona_Quest","steps":["Entre em Demona pela rota do Maze of Lost Souls. A partir do pentagrama, siga noroeste, desça e continue norte, oeste e norte.","Na biblioteca, examine as estantes do Purple Tome. A posição exata de cada estante não está desenhada neste guia.","A página atual contém criaturas e prêmios posteriores. A coleta no 7.4 permanece em revisão, sem prometer itens modernos.","A saída rápida é pelo teleport no ramo sudoeste da biblioteca, levando à região de Fields of Glory."],"status":"wiki-compared","patches":[]},"rapier":{"source":"https://www.tibiawiki.com.br/wiki/Rapier_Quest","steps":["Entre no esgoto principal de Rookgaard, em 32097, 32205, 7. Escolha o ramo oeste e desça pelo buraco.","Controle os Rats e procure o baú no canto nordeste do compartimento.","Use o baú para receber a Rapier e retorne pelo acesso do esgoto."],"status":"wiki-compared","patches":[]},"ring":{"source":"https://www.tibiawiki.com.br/wiki/The_Hero_Cave_Quest","steps":["Desça a Hero Cave até a área principal dos quatro quartos. Escolha os acessos dos dois anéis marcados neste guia.","Prepare Monks, Priestesses e as criaturas de cada compartimento antes de usar o baú; Heroes não aparecem igualmente em todos os quartos.","Abra separadamente os recipientes de Time Ring e Sword Ring. Retorne pelas escadas à área principal da Hero Cave."],"status":"wiki-compared","patches":[]},"scale-armor":{"source":"https://www.tibiawiki.com.br/wiki/Scale_Armor","steps":["Abra com Shovel o acesso da caverna a oeste do Ancient Temple, perto de 32337, 32172, 7.","Acompanhe o compartimento até o poço interno próximo de 32354, 32131, 8. Use o poço para alcançar o baú abaixo dele.","Abra o baú da Scale Armor e retorne pelo poço. O Wiki documenta o local nas notas do item; a existência precisa no clássico segue em revisão."],"status":"wiki-compared","patches":[]},"shaman-treasure":{"source":"https://www.tibiawiki.com.br/wiki/Against_the_Spider_Cult_Quest","steps":["Entre na Orc Cave de Edron pelo sudoeste. No primeiro subsolo, siga oeste e sul; no andar seguinte, oeste e norte.","Escolha o terceiro corredor para oeste e continue norte à sala da pedra sacrificial.","Examine o recipiente das três Blank Runes. Não é necessário começar a missão moderna de Daniel Steelsoul para esta coleta clássica."],"status":"wiki-compared","patches":[],"guideNote":"O Wiki reúne estas coletas em Against the Spider Cult (missão adicionada em 8.1). Este roteiro não exige Daniel Steelsoul nem destruir ovos."},"amber-s-notebook":{"source":"https://www.tibiawiki.com.br/wiki/Short_Sword_Quest","steps":["Vá à jangada da costa sudeste de Rookgaard, controlando os Bugs, Spiders e Poison Spiders do caminho.","Use o baú da jangada para obter Amber’s Notebook. Guarde o caderno na mochila.","Desça aos dormitórios da academia para falar com Amber: hi → book → yes. Ela recebe o notebook e entrega a Short Sword."],"status":"wiki-compared","patches":[{"stage":1,"speaker":"Amber","commands":["hi","book","yes"],"commandNote":"Leve Amber’s Notebook retirado da jangada."}]},"silver-amulet":{"source":"https://www.tibiawiki.com.br/wiki/Silver_Amulet","steps":["Abra com Shovel a entrada oriental da Troll Cave de Thais, em 32503, 32267, 7.","Desça pela escada sul da primeira sala até o compartimento do andar inferior.","A box do Silver Amulet fica junto à porta. O Wiki também identifica a coleta nas notas do item; confira o recipiente clássico no servidor."],"status":"wiki-compared","patches":[]},"silver-brooch":{"source":"https://www.tibiawiki.com.br/wiki/Silver_Brooch_Quest","steps":["Entre em Greenclaw Swamp pela caverna de 32700, 31991, 7. O acesso oeste pela Dwarf Bridge evita atravessar a região inteira do pântano.","No subsolo, siga leste e desça; continue sul à próxima queda e depois leste e sul à sala dos Bonelords.","Depois de limpar os Bonelords, use Pick no piso indicado. A sala abaixo é pequena e contém Mummies.","Examine o caixão ao norte para o Silver Brooch e as gemas. Leve Rope para subir sem ficar cercado."],"status":"wiki-compared","patches":[]},"six-rubies":{"source":"https://www.tibiawiki.com.br/index.php?stableid=330614&title=Thais_Quest","steps":["Entre no Ancient Temple e alcance o ramo dos dois Dragons. Prepare o combate antes de descer ao compartimento.","Na parte leste da sala, remova com Destroy Field o Fire Field que cobre o buraco.","Use o buraco para obter as seis Small Rubies; não desça automaticamente como se fosse uma passagem de andar.","A descrição continua disponível em revisões antigas da Thais Quest, mesmo sem uma página individual atual."],"status":"wiki-compared","patches":[]},"skull-of-ratha":{"source":"https://www.tibiawiki.com.br/wiki/The_Explorer_Society_Quest","steps":["Vá à Witch Hill no Amazon Camp ao norte de Venore. Controle Amazons, Valkyries e Witches antes dos recipientes.","Examine os dois recipientes da superfície para Skull of Ratha, White Pearl, Wolf Tooth Chain e Dwarven Ring.","Desça ao porão e procure o baú complementar marcado. Recolha todos os recipientes antes de retornar.","A entrega a Mortimer ou Angus faz parte da Explorer Society posterior ao 7.4; não é necessária para as coletas clássicas do acampamento."],"status":"wiki-compared","patches":[]},"small-ruby":{"source":"https://tibia.fandom.com/wiki/Small_Ruby_Quest/Spoiler","steps":["Acesse Mintwallin pelo labirinto do Ancient Temple e investigue o ramo abaixo da região do trono.","A gema é um respawn do mundo e pode já ter sido retirada. O ponto do buraco e o acesso continuam pendentes de confirmação nesta base.","Não siga uma linha de caminho inventada: use os marcos como referência e confira o servidor. Este registro permanece como coleta renovável, não como quest individual confirmada."],"status":"classic-reference","patches":[],"guideNote":"Respawn renovável com localização ainda em revisão. Não há solução individual suficientemente documentada no Wiki atual."},"spike-sword":{"source":"https://www.tibiawiki.com.br/wiki/Spike_Sword_Quest","steps":["Entre na pequena caverna a leste de Mount Sternum, próxima de 32594, 32067, 7. Desça ao piso dos Dwarfs e use Pick na passagem.","Na sala do Fire Devil, siga oeste e desça. Continue sul, controle os Fire Devils e abra com Pick a segunda passagem.","No andar de lava, os Fire Devils das ilhas continuam alcançando o jogador. Use o corpo escondido atrás do pilar para obter a Spike Sword.","Reserve cura e Rope para subir; invisibilidade não é garantia contra todas as criaturas e efeitos do servidor."],"status":"wiki-compared","patches":[]},"stealth-ring":{"source":"https://www.tibiawiki.com.br/wiki/Dark_Pyramid_Quest","steps":["Entre na Minotaur Pyramid de Darashia e desça até o andar dos recipientes, usando os marcos do mapa para escolher as passagens.","Os prêmios ficam em caixões separados no lado nordeste e no lado sudeste: Stealth Ring e Protection Amulet.","Recolha ambos e retorne pelas escadas da pirâmide. A página atual é Dark Pyramid Quest; não confunda esta coleta com os anéis de Demona."],"status":"wiki-compared","patches":[]},"steel-helmet":{"source":"https://www.tibiawiki.com.br/wiki/Steel_Helmet_Quest","steps":["Saia de Kazordoon e alcance a torre dos Minotaurs pelo túnel e pelo acesso de Shovel. Suba os andares controlando Archers, Guards e Mages.","No terceiro andar da torre, examine a gaveta norte e o recipiente sul do dinheiro.","No quarto andar, o baú norte contém o Steel Helmet e o sul contém o livro. Não confunda esses baús com os recipientes de ouro do andar abaixo.","Recolha os recipientes marcados e retorne pelo túnel, guardando Rope e Shovel."],"status":"wiki-compared","patches":[]},"honey-flower":{"source":"https://www.tibiawiki.com.br/wiki/Studded_Legs_Quest","steps":["Vá à Wasp Tower no noroeste de Rookgaard, em 32000, 32139, 7, levando Rope e cura de veneno.","Suba pelos pontos de Rope até o topo e use a flor para colher Honey Flower.","Leve a flor a Lee’Delle na área Premium e fale hi → honey flower. Aguarde a resposta: a troca entrega Studded Legs."],"status":"wiki-compared","patches":[{"stage":6,"speaker":"Lee'Delle","commands":["hi","honey flower"]}]},"banana":{"source":"https://www.tibiawiki.com.br/wiki/Studded_Shield_Quest","steps":["Use a Banana Palm a leste de Rookgaard, em 32172, 32169, 7. Essa opção Free evita a subida da palmeira Premium.","Guarde a Banana na mochila e volte a Willie, na fazenda da cidade.","Fale hi → banana → yes para receber Studded Shield. A conversa inicial sobre job e recipes é opcional."],"status":"wiki-compared","patches":[{"stage":1,"speaker":"Willie","commands":["hi","banana","yes"]}]},"thais-lighthouse":{"source":"https://www.tibiawiki.com.br/wiki/Thais_Quest","steps":["Leve pelo menos dois personagens ao farol sudoeste de Thais. Desça ao porão e retire as caixas que escondem a alavanca de acesso.","Um jogador permanece no piso de pressão do ramo norte para fazer aparecer a descida sul. O outro desce e aciona a alavanca inferior.","O mecanismo libera o teleport do ramo leste. Entre, controle os Cyclops e recolha Dark Shield e Battle Hammer nos baús ao norte.","Se ambos quiserem o prêmio, coordenem a troca de funções e repitam o acesso. Não abandone o piso antes de o parceiro alcançar a alavanca."],"status":"wiki-compared","patches":[{"stage":4,"action":"Um personagem fica no piso norte para manter a escada sul disponível. O parceiro desce e ativa a alavanca inferior."},{"stage":6,"action":"Ative o mecanismo e volte ao ramo leste. O teleport leva à sala dos dois baús e Cyclops."}]},"the-ancient-tombs":{"source":"https://www.tibiawiki.com.br/wiki/The_Ancient_Tombs_Quest","steps":["Abra cada entrada com Shovel; se necessário, use-a novamente até revelar a passagem. Leve Scarab Coins individuais para os Coal Basins.","Cada tumba tem um enigma antes do Pharaoh. Nas etapas abaixo, confira o item de passagem que cada jogador deve obter e a peça correspondente.","Omruc usa o labirinto de pisos; Thalas exige alavancas e falar com a estátua ainda envenenado; Dipthrah exige alavancas e as portas com palavras.","Mahrdis tem fogo roxo; Vashresamun exige instrumentos; Morguthis tem o labirinto com Deathslicers; Rahemos inclui mecanismos, paredes falsas e lava.","Depois das sete peças, complete Ashmunrah. Na sala da mesa, monte um capacete por vez; cada jogador coloca suas sete peças e entra e sai do piso.","Os marcos do atlas indicam entradas de tumbas, não as salas dos bosses. As subetapas e referências de enigma ficam em cada tumba."],"status":"wiki-compared","patches":[{"stage":0,"substeps":["Desça ao Coal Basin e fique na chama azul antes de oferecer a Scarab Coin.","Atravesse o portal do enigma pela sequência de pisos da referência, evitando atalhos pela sala.","Enfrente Omruc, obtenha Crystal Arrow individual e use a passagem para Helmet Adornment."],"visualRequired":true},{"stage":1,"substeps":["Depois da Scarab Coin, coordene as oito alavancas dentro do limite de tempo. Posicione o grupo antes da primeira.","Cada jogador pisa no interruptor de veneno e fala hi à estátua de cobra ainda envenenado.","Depois de Thalas, guarde Cobrafang Dagger e passe ao recipiente de Gem Holder."]},{"stage":2,"substeps":["No setor profundo da Mountain Tomb, acione as onze alavancas para liberar o portal.","Atravesse a porta 75+ e siga as palavras das placas na sequência abaixo.","Depois de Dipthrah, leve Ornamented Ankh à passagem de Damaged Helmet."],"sequence":["endless","pale-faced","deceased","unholy","doomed","righteous","sharpened","mortal"],"sequenceTitle":"Ordem das portas"},{"stage":3,"substeps":["No setor da chama, use Scarab Coin; siga oeste, desça e vá oeste e norte ao portal.","Suba a torre em espiral e passe 75+. Espere o fogo roxo apagar no próximo piso antes de avançar.","Depois de Mahrdis, leve Burning Heart à passagem de Helmet Ornament."]},{"stage":4,"sequence":["Tambor (noroeste)","Xilofone (sul, centro)","Harpa (norte, centro)","Lira (sudoeste)","Lute (sudeste)"],"sequenceTitle":"Ordem dos instrumentos","action":"Use cada instrumento na ordem; a flauta do nordeste não entra nessa sequência."},{"stage":5,"substeps":["Entre pelo Coal Basin e alcance o labirinto depois da sala de Behemoths e Warlock.","Nos ramos de Deathslicers, um blocker mantém a criatura afastada enquanto o grupo passa aos alçapões. Há salas que exigem dois blockers.","Distinga buracos, Rope spots e teleports: não são intercambiáveis. Confira cada mudança na referência de Morguthis antes de avançar.","No fim, enfrente Morguthis e leve Sword Hilt à passagem de Right Horn."],"visualRequired":true},{"stage":6,"substeps":["Depois da Scarab Coin, atravesse a área profunda até a porta 75+.","Resolva o mecanismo da cenoura antes da porta selada. Erros nesse mecanismo causam dano.","Passe pelas paredes falsas e pela lava ao lado da ponte conforme a referência.","Depois de Rahemos, leve Ancient Rune à passagem de Helmet Piece."],"visualRequired":true},{"stage":7,"substeps":["Passe pelo Coal Basin e pelos corredores de armadilhas até Ashmunrah.","Depois do boss, deixe as alavancas na posição que libera o teleport para cada participante.","Um por vez, coloque sete peças na mesa; entre e saia do piso especial para receber o Helmet of the Ancients."]}]},"the-desert-dungeon":{"source":"https://www.tibiawiki.com.br/wiki/The_Desert_Dungeon_Quest","steps":["Abra a entrada de Jakundaf com Shovel e desça pelo acesso clássico. Reúna Knight, Paladin, Druid e Sorcerer, todos de nível 20 ou mais.","Coloque Sword, Crossbow, Apple e Spellbook nos altares correspondentes. Os personagens ficam nos pisos; não no mesmo SQM dos itens.","Confira os quatro personagens e os quatro objetos antes da alavanca. O mapa de cada vocação informa o piso e a ação informa a coordenada do altar.","Acione o mecanismo com a equipe posicionada. Na sala final, recolha os dois recipientes e use a saída disponível no servidor. Monk e quinto participante não fazem parte desta configuração 7.4."],"status":"wiki-compared","patches":[]},"the-djinn-war-efreet-faction":{"source":"https://www.tibiawiki.com.br/wiki/The_Djinn_War_Quest","steps":["Aprenda DJANNI’HAH com Melchior e escolha a facção verde com Ubaid. A escolha é permanente.","Investigue o prisioneiro com Shauna e Partos; informe o nome a Baa’leal. Não cumprimente o general com hi.","Aceite de Alesar a tarefa da Tear of Daraman. Use a entrada secreta da torre azul e a fonte norte; leve a gema de volta.","Peça a missão final a Malor. Na Orc Fortress, prepare os summons do primeiro hi e depois peça lamp → malor.","Use a Gemmed Lamp na lâmpada do quarto de Gabel e reporte a Malor. Os trechos de Orc Fortress estão incluídos no mapa; viagens entre cidades não são linhas de caminhada."],"status":"wiki-compared","patches":[]},"the-djinn-war-marid-faction":{"source":"https://www.tibiawiki.com.br/wiki/The_Djinn_War_Quest","steps":["Aprenda DJANNI’HAH com Melchior e escolha a facção azul com Umar. A escolha é permanente.","Aceite a missão de Bo’ques, compre o Cookbook com Maryza por 150 gp e entregue-o ao cozinheiro.","Peça a Fa’hradin a tarefa do relatório. Infiltre a torre verde pelos fundos levando Cheese; cumprimente Rata’mari com PIEDPIPER.","Entregue o Spy Report e aceite a tarefa final de Gabel. Na Orc Fortress, prepare os summons e obtenha a Gemmed Lamp.","Use a lamp na lâmpada do quarto de Malor e volte a Gabel para liberar o comércio. O guia mantém as falas e ações na ordem das etapas."],"status":"wiki-compared","patches":[]},"the-outlaw-camp":{"source":"https://www.tibiawiki.com.br/wiki/The_Outlaw_Camp_Quest","steps":["Pegue 3301, 3302 e 3303 nas três árvores do acampamento. Entre na caverna dos Wild Warriors e abra a porta da alavanca com 3303.","Acione o forno; suba e desça pelo ramo sul para obter 3304 no baú atrás dele. Prepare Rope, Power Ring, Barrel leve e Parcels ou Levitate.","Coloque o barril na caverna junto à água antes da descida sem retorno da torre. Leve-o ao canto noroeste para recuperá-lo por Rope mais adiante.","Na área dos Orcs, coloque o Power Ring na mesa do ramo esquerdo e acione a alavanca. No ramo direito, puxe o barril pelo buraco e leve-o à brecha da parede após a porta de nível 45.","Retorne pelos acessos 3301 e 3302 ao moinho e acione a alavanca final somente depois de posicionar o barril. Volte à parede, elimine Demon Skeletons e abra a porta 3304.","Recolha Bright Sword e Red Gem. A alavanca final tem limite diário; errar o tipo ou a posição do barril pode obrigar a esperar o próximo reset."],"status":"wiki-compared","patches":[{"stage":7,"action":"Use o Barrel leve. Primeiro coloque-o no canto noroeste da caverna da água; depois recupere-o por Rope pelo acesso superior.","warning":"Posicionar o barril faz parte da preparação anterior à alavanca final."},{"stage":10,"action":"Coloque o Power Ring na mesa e use a alavanca. O anel é transferido para o mecanismo do moinho, não entregue a um NPC."},{"stage":12,"action":"Leve o barril pela porta de nível 45 e coloque-o na brecha da parede. Ele limita o movimento da parede para formar a passagem."},{"stage":20,"warning":"Mecanismo com limite diário. Só acione depois de conferir o tipo e a posição do barril.","action":"O Power Ring vira um Fire Field. Volte à parede, elimine os Demon Skeletons e abra 3304 para os prêmios."}],"needs":["Barrel leve correto","Keys 3301, 3302, 3303 e 3304","Power Ring","Rope","Levitate ou Parcels"]},"the-paradox-tower":{"source":"https://www.tibiawiki.com.br/wiki/The_Paradox_Tower_Quest","steps":["Investigue Hugo na ordem Oldrak → Zoltan → Padreia → Lubo. As palavras-chave de cada conversa estão nas etapas dos NPCs.","Pegue 3899 na árvore ao norte da torre. Suba a montanha com Levitate ou Parcels e coloque um Skull em cada um dos quatro altares.","Corte a grama e espere a entrada começar a crescer antes de acionar o piso da escada. Ajuste as seis alavancas: direita, direita, esquerda, esquerda, direita, esquerda.","Espere o Ghoul no canto noroeste para subir. Use 3899; organize as frutas: Melon, Banana, Cherry, Apple, Grapes, Coconut. Resolva o xadrez conforme as estátuas.","Responda ao primeiro teste de Riddler até 1+1. Depois da expulsão, visite A Prisoner em Mintwallin para descobrir seu número individual.","Anote o número: no 7.4 não há Quest Log para recuperá-lo. Refaça a torre, repita o teste e responda esse número no final.","Cada piso do tesouro elimina uma recompensa. Planeje os dois prêmios antes de pisar; use a referência visual e saia pelo Strange Carving ao sul."],"status":"wiki-compared","patches":[{"stage":0,"speaker":"Oldrak","commands":["hi","hugo","myth","yenny the gentle"]},{"stage":1,"speaker":"Zoltan","commands":["hi","yenny the gentle","crunors caress"]},{"stage":2,"speaker":"Padreia","commands":["hi","crunor's caress","footnote"]},{"stage":3,"speaker":"Lubo","commands":["hi","crunor's cottage","flower guys","accident","stable"]},{"stage":16,"speaker":"Riddler","commands":["hi","test","yes","goshnar","demonbunny","tha'kull","yes","breath","silence","old","yes","green","none"],"commandNote":"Ao chegar à pergunta 1+1, dê um número para seguir à expulsão para Hellgate. Ainda falta descobrir o número individual com A Prisoner.","warning":"Complete antes as quatro investigações. Errar outra pergunta interrompe o teste.","detailSource":"https://www.tibiawiki.com.br/wiki/Riddler"},{"stage":17,"speaker":"A Prisoner","commands":["hi","math","yes"],"commandNote":"Se perguntar a cor, responda green; confirme yes quando pedir para continuar. Anote o número que o NPC revelar. Não existe resposta universal.","warning":"Visite-o somente depois do primeiro teste de Riddler. No 7.4, anote o número fora do Quest Log.","detailSource":"https://www.tibiawiki.com.br/wiki/The_Paradox_Tower_Quest#Falando_com_o_prisioneiro_em_Mintwallin"},{"stage":18,"speaker":"Riddler","commands":["hi","test","yes","goshnar","demonbunny","tha'kull","yes","breath","silence","old","yes","green","none"],"commandNote":"Na última pergunta (1+1), digite manualmente o seu número, recebido do prisioneiro. Não copie um número de outro personagem.","detailSource":"https://www.tibiawiki.com.br/wiki/Riddler"},{"stage":8,"action":"Posições da esquerda para a direita; confira todas antes de tentar a escada.","sequence":["Direita","Direita","Esquerda","Esquerda","Direita","Esquerda"],"sequenceTitle":"Posição das seis alavancas"},{"stage":10,"action":"Acione a alavanca. Quando o Ghoul chegar ao canto noroeste, suba imediatamente; se ele sair dali, a escada desaparece."},{"stage":13,"action":"Depois da porta 3899, coloque as frutas da esquerda para a direita e puxe a alavanca.","sequence":["Melon","Banana","Cherry","Apple","Grapes","Coconut"],"sequenceTitle":"Ordem das frutas"},{"stage":15,"action":"Dê look nas duas estátuas da parede norte; coloque White Knight e Black Knight nos lados correspondentes, então use a alavanca.","visualRequired":true},{"stage":19,"warning":"Os pisos removem prêmios. Não ande pela sala inteira antes de decidir quais dois deseja.","action":"As letras da imagem indicam o prêmio eliminado, não o prêmio recebido. Saia pelo Strange Carving ao sul.","visualRequired":true,"detailSource":"https://www.tibiawiki.com.br/wiki/The_Paradox_Tower_Quest#Segunda_visita_a_Paradox_Tower"}],"needs":["8 Skulls para as duas visitas (4 em cada ida)","Levitate ou Parcels para a subida","Anotar o número individual do prisioneiro fora do jogo"],"guideNote":"O clássico oferece Wooden Wand, não Wand of Cosmic Energy. O número do prisioneiro é individual; não há Quest Log no 7.4.","removeNeeds":["4 Skulls"]},"the-queen-of-the-banshees":{"source":"https://www.tibiawiki.com.br/wiki/The_Queen_of_the_Banshees_Quest","steps":["Entre em Ghostlands e use os dois mecanismos das Magic Walls. Depois das paredes, desça pelo buraco; o teleport é a saída.","Hidden: abra a passagem com Pick e atravesse a chama. Logic: ajuste as seis alavancas. True Path: siga somente os pisos do desenho.","Sacrifice: despeje Blood entre as pedras. Demonrage: prepare Warlocks e a ordem das alavancas. Plague: cada jogador oferece suas duas pérolas.","Cada participante precisa atravessar a chama de cada selo e retornar pelo teleport. Fazer o mecanismo para a equipe não registra automaticamente todos os personagens.","Fale com a Queen depois dos seis selos. O beijo leva à lápide; refaça o acesso para as portas finais de nível 60.","Prepare a batalha final e recolha os quatro baús antes da saída. Os diagramas mostram mecanismos; as ligações sem linha no atlas continuam pendentes de validação."],"status":"wiki-compared","patches":[{"stage":8,"action":"As duas fileiras ficam iguais: direita, direita, esquerda, olhando de oeste para leste. Depois atravesse a chama e retorne.","leverRows":[["Direita","Direita","Esquerda"],["Direita","Direita","Esquerda"]]},{"stage":12,"action":"Chegue pela escada oeste à área lisa; entre no piso 1 e siga os números até a chama azul. Retorne pelo teleport.","diagram":"assets/quest-diagrams/banshee-true-path.svg"},{"stage":14,"sequence":["2ª","4ª","3ª","1ª","5ª"],"sequenceTitle":"Ordem de acionamento · alavancas contadas do norte para o sul","action":"Depois dos Warlocks, acione os mecanismos na ordem e atravesse a chama azul. O desenho original numera a sequência por moedas."}],"needs":["Pick","Blood","Uma Black Pearl e uma White Pearl por participante"]},"the-white-raven-monastery":{"source":"https://www.tibiawiki.com.br/wiki/The_White_Raven_Monastery_Quest","steps":["Entre em Ghostlands pelo acesso sob o muro ao sul de Dalbrect. Vá à casa abandonada e desça ao corredor dos mortos-vivos.","Siga sul, desça; no andar inferior, vá leste ao fim e sul à sala. Suba e use a parte superior do caixão norte para obter Family Brooch.","Entregue o brooch a Dalbrect e peça passage para Isle of the Kings. Na ilha, aceite de Costello a investigação sobre Fugio.","Retorne a Ghostlands e alcance as duas alavancas das Magic Walls. Ative ambas; depois das paredes, use o buraco, não o teleport de saída.","No corpo da sala dos mortos-vivos, recolha Monk’s Diary. Volte a Costello e entregue o diário para Blessed Ankh.","O diário é uma coleta diferente dos selos da Banshee Quest. Não é necessário concluir os sete selos para esta investigação."],"status":"wiki-compared","patches":[{"stage":5,"speaker":"Dalbrect","commands":["hi","brooch","yes","yes","passage","yes"],"warning":"Leve Family Brooch e 10 gp para a passagem. Confirme cada pergunta separadamente."},{"stage":6,"speaker":"Costello","commands":["hi","fugio","yes"],"detailSource":"https://www.tibiawiki.com.br/wiki/Costello"},{"stage":9,"speaker":"Costello","commands":["hi","diary","yes"],"detailSource":"https://www.tibiawiki.com.br/wiki/Costello"},{"stage":4,"action":"Use a parte superior do caixão norte. O brooch é entregue a Dalbrect para liberar a ilha."},{"stage":8,"action":"Examine o corpo no meio da sala depois das Magic Walls. Guarde o diário e leve-o de volta a Costello."}],"needs":["10 gp por passagem à Isle of the Kings"]},"throwing-star":{"source":"https://tibia.fandom.com/index.php?oldid=24062","steps":["Entre no Ancient Temple e alcance o ramo do labirinto onde fica a passagem de Pick marcada no guia.","Use Pick, desça ao compartimento inferior e examine o recipiente das Throwing Stars.","O Wiki atual não apresenta uma página própria dessa coleta. O percurso e o ponto de Pick permanecem como referência clássica aproximada, a conferir no servidor."],"status":"classic-reference","patches":[],"guideNote":"Não foi localizada página específica atual no Wiki. Mantidas as referências históricas e os marcos aproximados; o percurso precisa de confirmação no jogo."},"time-ring":{"source":"https://www.tibiawiki.com.br/wiki/Shadowthorn_Quest","steps":["Entre em Shadowthorn e suba à muralha pelo ramo oeste. Desça pela escada próxima de 33061, 32173, 6.","Siga sudoeste e oeste à sala de elfos e mortos-vivos. Desça a rampa com preparo para Elf Arcanists, Scouts, Ghouls e Demon Skeleton.","Os três recipientes de Time Ring, Elven Amulet e Crystal Ball ficam ao norte. Recolha os três antes de refazer a subida.","A torre dos Dragons é outra coleta da mesma região; montarias e Thornfire da página atual não são etapas deste guia 7.4."],"status":"wiki-compared","patches":[]},"torch":{"source":"https://www.tibiawiki.com.br/wiki/Torch_Quest","steps":["Desça ao porão da academia de Rookgaard e siga norte pelo corredor, abrindo as portas do caminho.","Acione a passagem indicada no mapa se ela estiver fechada. O baú da Torch fica no fim do corredor, na área de um Rat.","Esta é uma coleta histórica removida de versões atuais. A página obsoleta do Wiki é referência histórica; confirme se o servidor 7.4 mantém o recipiente."],"status":"wiki-compared","patches":[]},"triangle-tower":{"source":"https://www.tibiawiki.com.br/wiki/Triangle_Tower_Quest","steps":["Chegue à Triangle Tower em 32562, 32117, 7. Se a entrada estiver fechada, use a alavanca escondida de Jakundaf, próxima de 32574, 32121, 7.","Suba os andares de Skeletons, Ghouls e Demon Skeletons. No topo, prepare Dwarf Geomancer, Monk e Witch.","Abra o baú dos prêmios. Se a porta de entrada for fechada enquanto estiver na torre, o teleport do porão é a alternativa de saída."],"status":"wiki-compared","patches":[{"stage":1,"action":"Acione esta alavanca se a torre estiver fechada. Caso a entrada se feche depois, há um teleport de saída no porão."}]},"triple-uh-rune":{"source":"https://www.tibiawiki.com.br/wiki/The_Hero_Cave_Quest","steps":["Desça a Hero Cave à região dos quatro quartos. Procure a sala da UH marcada neste guia, controlando as criaturas junto à escada.","Abra o recipiente da recompensa clássica e confira as três cargas da UH no seu servidor.","A página moderna mostra Silver Rune Emblem e potions no lugar de itens antigos. Essa alteração não deve ser aplicada automaticamente ao 7.4."],"status":"wiki-compared","patches":[]},"troll-cave":{"source":"https://www.tibiawiki.com.br/wiki/Troll_Cave_Quest","steps":["Desça no esgoto a sudoeste do depot de Edron e siga o túnel até a área de grama. Vá norte à entrada dos Trolls.","Na caverna, siga norte e leste, desça; no andar seguinte, continue norte ao buraco inferior.","Limpe as criaturas perto dos dois baús no lado leste. Recolha Brass Legs e Garlic Necklace antes de refazer as subidas."],"status":"wiki-compared","patches":[]},"vampire-shield":{"source":"https://www.tibiawiki.com.br/wiki/The_Hero_Cave_Quest","steps":["Desça a Hero Cave à área principal e siga sul, depois leste até o cruzamento; escolha o ramo sul e desça ao Temple of Xayepocax.","Prepare Heroes, Priestesses, Witches, Monk, Orc Shaman e Warlock antes dos baús.","Examine os recipientes exteriores e atravesse a porta de nível 70 para Dragon Lance e Vampire Shield. Os dois prêmios têm marcos separados no guia.","Reserve suprimentos para a volta pela Hero Cave; não dependa de criaturas ou prêmios modernos adicionados às outras salas."],"status":"wiki-compared","patches":[]},"voodoo-doll":{"source":"https://www.tibiawiki.com.br/wiki/Voodoo_Doll_Quest","steps":["Vá ao acesso norte de Greenclaw Swamp, próximo de 32739, 31952, 7, chegando pelo oeste ou pela saída noroeste de Venore.","Desça, siga diretamente oeste e desça outra vez. Prepare as Witches do compartimento inferior.","O baú fica na sala grande a leste, junto à parede. Recolha Voodoo Doll e Magic Light Wand e retorne com Rope."],"status":"wiki-compared","patches":[]},"wedding-ring":{"source":"https://www.tibiawiki.com.br/wiki/The_Hero_Cave_Quest","steps":["Desça a Hero Cave à área dos quatro quartos. Escolha o ramo da Wedding Ring indicado no mapa, mantendo cura para a entrada.","Controle as criaturas da sala e examine o recipiente do anel; o Dragon Necklace fica num recipiente separado.","Recolha ambos e retorne à área principal pelas escadas do quarto. O roteiro moderno reúne esta coleta com outras salas da Hero Cave."],"status":"wiki-compared","patches":[]},"serpentine-tower":{"source":"https://www.tibiawiki.com.br/wiki/Serpentine_Tower_Quest","steps":["Entre na Serpentine Tower em Ankrahmun e alcance a sala da Pot. Afaste a Pot que cobre o fogo para liberar a passagem secreta.","Passe pelo Forcefield do acesso e recolha a White Pearl no pequeno quarto. Essa é a coleta comprovada deste guia.","Não confunda as especulações sobre criaturas enjauladas com uma solução completa da torre. Usar a tocha pode liberar o Fire Elemental, então não a acione sem preparo."],"status":"wiki-compared","patches":[{"stage":1,"action":"Mova a Pot que cobre o fogo para revelar o mecanismo da passagem da White Pearl. Não use a tocha sem preparo para o Fire Elemental."}]}};
window.QUEST_WIKI_REVIEW=review;
for(const [id,r] of Object.entries(review)){
 const q=QUESTS.find(q=>q.id===id),route=window.QUEST_ROUTES[id];if(!q||!route)throw new Error('Quest ausente: '+id);
 q.steps=r.steps;q.needs=q.needs.filter(n=>!(r.removeNeeds||[]).includes(n));q.needs=[...new Set([...q.needs,...(r.needs||[])])];
 if(r.rewards)q.rewards=r.rewards;if(r.rewardNote)q.rewardNote=r.rewardNote;
 q.guideReviewNote=r.guideNote||(r.status==='classic-reference'?'Referência clássica: detalhes ainda precisam de confirmação em fonte histórica.':'Roteiro comparado com o TibiaWiki. Mecânicas posteriores ao 7.4 foram separadas; os caminhos ainda precisam de validação no jogo.');
 q.sources=[...new Set([r.source,...q.sources])];q.reviewedAt='13/10/2026';
 for(const patch of r.patches||[]){if(!route.stages[patch.stage])throw new Error('Etapa ausente: '+id+' '+patch.stage);const {stage,...fields}=patch;Object.assign(route.stages[stage],fields);}
 for(const s of route.stages){s.detailSource=s.detailSource||r.source;}
}
window.QUEST_DETAIL_IDS=Object.keys(review);
const original=window.questStageExtras;
const safe=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
window.questStageExtras=(id,i)=>{const s=window.QUEST_ROUTES[id]?.stages[i];if(!s)return '';let extra='';
 if(s.sequence?.length)extra+=`<div class="guide-mechanism"><b>${safe(s.sequenceTitle||'Ordem do mecanismo')}</b><ol>${s.sequence.map(v=>`<li>${safe(v)}</li>`).join('')}</ol></div>`;
 if(s.leverRows)extra+=`<div class="guide-mechanism"><table><caption>Posição final das alavancas · oeste → leste</caption><thead><tr><th>Fileira</th><th>Oeste</th><th>Centro</th><th>Leste</th></tr></thead><tbody>${s.leverRows.map((row,n)=>`<tr><th>${n?'Sul':'Norte'}</th>${row.map(v=>`<td>${safe(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
 if(s.substeps?.length)extra+=`<ol class="guide-substeps">${s.substeps.map(v=>`<li>${safe(v)}</li>`).join('')}</ol>`;
 if(s.diagram)extra+=`<figure class="guide-puzzle"><a href="${safe(s.diagram)}" target="_blank" rel="noopener"><img src="${safe(s.diagram)}" alt="Piso da Banshee: siga as casas numeradas de 1 a 8 e entre na chama azul." loading="lazy"></a><figcaption>Esquema do enigma. Confira a posição da escada na sala; não são coordenadas do atlas.</figcaption></figure>`;
 return original(id,i)+extra;
};
})();
